function renderList(products) {
  const items = products.map((product) => {
    const className = product.soldOut ? 'item item--soldout' : 'item';

    return `<li class="${className}">${product.name} - ${product.price}원</li>`;
  });

  return `<ul class="list">${items.join('')}</ul>`;
}
